supplyDemandQuery.xPath:
declare function local:append-heirarchy($parent as node(), $append as node()*) as node() {
    let $scn := $parent/ancestor::scenario,
        $rgn := $parent (: /ancestor::region :)
    return
        document { element scenario {
            $scn/@*,
            element region {
                $rgn/@*,
                $append
            }
        }}
};
declare function local:run-emiss-factors($scenarios as xs:string*, $regions as xs:string*, $collection as xs:string) as node()* {
    unordered {
    let $regionsG := if(not($regions[1] = 'Global'))
        then $regions
        else distinct-values(collection($collection)/scenario/world/*[@type='region']/@name)
    return
    for $scenario in $scenarios,
        $region in $regionsG
    let $scenario_split := tokenize($scenario, ' '),
        $scenario_name  := string-join($scenario_split[position() < last()], ' '),
        $scenario_date  := $scenario_split[last()],
        $currTree := collection($collection)/scenario[@name = $scenario_name and @date = $scenario_date]/world/*[@type = 'region' and @name=$region]
    for $sector in $currTree/*[@type='sector']
    for $subsector in $sector/*[@type='subsector']
    (: group by technology name, aggregating across all vintage years :)
    for $tech_name in distinct-values($subsector//*[@type='technology']/@name)
    let $tech_vintages := $subsector//*[@type='technology' and @name=$tech_name]
    for $ghg_name in distinct-values($tech_vintages/*[@type='GHG']/@name)
    where $ghg_name = ('CO2', 'NOx', 'SO2', 'PM2.5', 'PM10', 'CO', 'NH3')
    (: collect all GHG nodes across every vintage for this tech and pollutant :)
    let $all_ghg := $tech_vintages/*[@type='GHG' and @name=$ghg_name]
    for $year in distinct-values($all_ghg/emissions/@year)
    (: sum emissions and output across all vintages operating in $year :)
    let $total_emiss  := sum($all_ghg/emissions[@year=$year])
    let $total_output := sum($tech_vintages/output-primary[@type='output']/physical-output[@vintage=$year])
    let $emiss_unit   := string(($all_ghg/emissions[@year=$year]/@unit)[1])
    let $output_unit  := string(($tech_vintages/output-primary[@type='output']/physical-output[@vintage=$year]/@unit)[1])
    where $total_output > 0 and $total_emiss != 0
    return local:append-heirarchy($currTree,
        element { local-name($sector) } { $sector/@*,
            element { local-name($subsector) } { $subsector/@*,
                element technology {
                    attribute name { $tech_name },
                    attribute type { 'technology' },
                    element GHG {
                        attribute name { $ghg_name },
                        attribute type { 'GHG' },
                        element emissions {
                            attribute year { $year },
                            attribute unit { concat($emiss_unit, '/', $output_unit) },
                            text { $total_emiss div $total_output }
                        }
                    }
                }
            }
        }
    )//text()
    }
};
local:run-emiss-factors((:scenarios:), (:regions:), (:collection:))

declare function local:append-heirarchy($parent as node(), $append as node()*) as node() {
    let $scn := $parent/ancestor::scenario,
        $rgn := $parent (: /ancestor::region :)
    return
        document { element scenario {
            $scn/@*,
            element region {
                $rgn/@*,
                $append
            }
        }}
};
declare function local:run-energy-intensity($scenarios as xs:string*, $regions as xs:string*, $collection as xs:string) as node()* {
    unordered {
    let $regionsG := if(not($regions[1] = 'Global'))
        then $regions
        else distinct-values(collection($collection)/scenario/world/*[@type='region']/@name)
    return
    for $scenario in $scenarios,
        $region in $regionsG
    let $scenario_split := tokenize($scenario, ' '),
        $scenario_name  := string-join($scenario_split[position() < last()], ' '),
        $scenario_date  := $scenario_split[last()],
        $currTree := collection($collection)/scenario[@name = $scenario_name and @date = $scenario_date]/world/*[@type = 'region' and @name=$region]
    for $sector in $currTree/*[@type='sector']
    for $subsector in $sector/*[@type='subsector']
    (: group by technology name, aggregating across all vintage years :)
    for $tech_name in distinct-values($subsector//*[@type='technology']/@name)
    let $tech_vintages := $subsector//*[@type='technology' and @name=$tech_name]
    (: collect all energy inputs, excluding water routing inputs :)
    let $all_inputs := $tech_vintages/input-energy[not(starts-with(@name, 'water_td'))]
    for $year in distinct-values($tech_vintages/output-primary[@type='output']/physical-output/@vintage)
    (: sum all energy inputs and primary output across all vintages for this year :)
    let $total_input  := sum($all_inputs/demand-physical[@vintage=$year])
    let $total_output := sum($tech_vintages/output-primary[@type='output']/physical-output[@vintage=$year])
    let $input_unit   := string(($all_inputs/demand-physical[@vintage=$year]/@unit)[1])
    let $output_unit  := string(($tech_vintages/output-primary[@type='output']/physical-output[@vintage=$year]/@unit)[1])
    where $total_output > 0 and $total_input > 0
    return local:append-heirarchy($currTree,
        element { local-name($sector) } { $sector/@*,
            element { local-name($subsector) } { $subsector/@*,
                element technology {
                    attribute name { $tech_name },
                    attribute type { 'technology' },
                    element input {
                        attribute name { 'energy-intensity' },
                        attribute type { 'input' },
                        element demand-physical {
                            attribute vintage { $year },
                            attribute unit { concat($input_unit, '/', $output_unit) },
                            text { $total_input div $total_output }
                        }
                    }
                }
            }
        }
    )//text()
    }
};
local:run-energy-intensity((:scenarios:), (:regions:), (:collection:))

