declare function local:run-sales-share($scenarios as xs:string*, $regions as xs:string*, $collection as xs:string) as node()* {
    unordered {
    let $regionsG := if(not($regions[1] = 'Global'))
        then $regions
        else distinct-values(collection($collection)/scenario/world/*[@type='region']/@name)
    return
    for $scenario in $scenarios,
        $region in $regionsG
    let $scenario_split := tokenize($scenario, ' '),
        $scenario_name  := string-join($scenario_split[position() < last()], ' '),
        $scenario_date  := $scenario_split[last()],
        $currTree := collection($collection)/scenario[@name = $scenario_name and @date = $scenario_date]/world/*[@type = 'region' and @name=$region]
    for $sector in $currTree/*[@type='sector']
    for $subsector in $sector/*[@type='subsector']
    for $tech_name in distinct-values($subsector//*[@type='technology']/@name)
    (: iterate over vintage years (installation years) for this technology :)
    for $year in distinct-values($subsector//*[@type='technology' and @name=$tech_name]/@year)
    (: select only the vintage node installed in year $year :)
    let $tech_vintage := $subsector//*[@type='technology' and @name=$tech_name and @year=$year]
    (: output of this technology's vintage-$year installation in model year $year (sales) :)
    let $tech_sales := sum($tech_vintage/output-primary[@type='output']/physical-output[@vintage=$year])
    (: output of ALL technologies' vintage-$year installations in model year $year :)
    let $subsector_sales := sum($subsector//*[@type='technology' and @year=$year]/output-primary[@type='output']/physical-output[@vintage=$year])
    where $subsector_sales > 0 and $tech_sales > 0
    return local:append-heirarchy($currTree,
        element { local-name($sector) } { $sector/@*,
            element { local-name($subsector) } { $subsector/@*,
                element technology {
                    attribute name { $tech_name },
                    attribute type { 'technology' },
                    element input {
                        attribute name { 'sales-share' },
                        attribute type { 'input' },
                        element demand-physical {
                            attribute vintage { $year },
                            attribute unit { '%' },
                            text { ($tech_sales div $subsector_sales) * 100 }
                        }
                    }
                }
            }
        }
    )//text()
    }
};
local:run-sales-share((:scenarios:), (:regions:), (:collection:))

