declare function local:run-stock-share($scenarios as xs:string*, $regions as xs:string*, $collection as xs:string) as node()* {
    unordered {
    let $regionsG := if(not($regions[1] = 'Global'))
        then $regions
        else distinct-values(collection($collection)/scenario/world/*[@type='region']/@name)
    return
    for $scenario in $scenarios,
        $region in $regionsG
    let $scenario_split := tokenize($scenario, ' '),
        $scenario_name  := string-join($scenario_split[position() < last()], ' '),
        $scenario_date  := $scenario_split[last()],
        $currTree := collection($collection)/scenario[@name = $scenario_name and @date = $scenario_date]/world/*[@type = 'region' and @name=$region]
    for $sector in $currTree/*[@type='sector']
    for $tech_name in distinct-values($sector//*[@type='technology']/@name)
    (: iterate over model years (all years in which any vintage produced output) :)
    for $year in distinct-values($sector//*[@type='technology']/output-primary[@type='output']/physical-output/@vintage)
    (: total output of this tech across ALL vintages in model year $year :)
    let $tech_output := sum($sector//*[@type='technology' and @name=$tech_name]/output-primary[@type='output']/physical-output[@vintage=$year])
    (: total output of ALL techs in this sector in model year $year :)
    let $sector_output := sum($sector//*[@type='technology']/output-primary[@type='output']/physical-output[@vintage=$year])
    where $sector_output > 0 and $tech_output > 0
    return local:append-heirarchy($currTree,
        element { local-name($sector) } { $sector/@*,
            element technology {
                attribute name { $tech_name },
                attribute type { 'technology' },
                element input {
                    attribute name { 'stock-share' },
                    attribute type { 'input' },
                    element demand-physical {
                        attribute vintage { $year },
                        attribute unit { '%' },
                        text { ($tech_output div $sector_output) * 100 }
                    }
                }
            }
        }
    )//text()
    }
};
local:run-stock-share((:scenarios:), (:regions:), (:collection:))

